package com.domesticservice.finance.application;

import com.domesticservice.common.web.ServiceHttpClient;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.ObjectMapper;

@Service
public class FinanceOperationsService {
    private final JdbcTemplate db;private final ObjectMapper json;private final ServiceHttpClient identity,booking;
    public FinanceOperationsService(JdbcTemplate db,ObjectMapper json,@Value("${clients.identity.base-url}")String identityUrl,@Value("${clients.booking.base-url}")String bookingUrl){this.db=db;this.json=json;identity=new ServiceHttpClient(identityUrl);booking=new ServiceHttpClient(bookingUrl);}
    static ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
    static String text(Map<String,Object>b,String key,int max,boolean required){String s=Objects.toString(b.get(key),"").strip();if(s.length()>max||required&&s.isBlank())throw bad("Vui lòng kiểm tra "+key+".");return s;}
    static long number(Map<String,Object>b,String key,long min,long max){try{long value=Long.parseLong(Objects.toString(b.get(key),""));if(value<min||value>max)throw bad("Giá trị "+key+" không hợp lệ.");return value;}catch(NumberFormatException ex){throw bad("Giá trị "+key+" không hợp lệ.");}}
    private long insert(String sql,Object...args){var key=new GeneratedKeyHolder();db.update(c->{var s=c.prepareStatement(sql,new String[]{"id"});for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);return s;},key);return Objects.requireNonNull(key.getKey()).longValue();}
    private Map<String,Object> balance(long staff,boolean lock){if(lock)db.update("INSERT INTO staff_balances(staff_id) VALUES (?) ON CONFLICT(staff_id) DO NOTHING",staff);var rows=db.queryForList("SELECT * FROM staff_balances WHERE staff_id=?"+(lock?" FOR UPDATE":""),staff);return rows.isEmpty()?Map.of("available_balance",0L,"pending_balance",0L,"reserved_balance",0L,"total_earned",0L,"withdrawn_amount",0L):rows.getFirst();}
    public Map<String,Object>wallet(String token,Long staffId){var user=identity.authenticate(token,"STAFF","ADMIN");long staff=staffId==null?ServiceHttpClient.userId(user):staffId;if(!"ADMIN".equals(user.get("role"))&&staff!=ServiceHttpClient.userId(user))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Bạn không có quyền xem số dư này.");var b=balance(staff,false);var ledger=db.queryForList("SELECT t.id,t.direction,t.bucket,t.transaction_type AS type,t.amount,t.created_at AS \"createdAt\",t.reference_id AS \"referenceId\" FROM wallet_transactions t JOIN staff_balances b ON b.id=t.balance_id WHERE b.staff_id=? ORDER BY t.created_at DESC,t.id DESC",staff);return Map.of("balance",Map.of("available",b.get("available_balance"),"pending",b.get("pending_balance"),"reserved",b.get("reserved_balance"),"totalEarned",b.get("total_earned"),"withdrawn",b.get("withdrawn_amount")),"transactions",ledger,"incomes",db.queryForList("SELECT id,booking_id AS \"bookingId\",working_hours AS \"workingHours\",service_amount AS \"serviceAmount\",platform_fee AS \"platformFee\",staff_amount AS \"staffAmount\",status,income_date AS \"incomeDate\" FROM staff_incomes WHERE staff_id=? ORDER BY id DESC",staff),"withdrawals",db.queryForList("SELECT id,amount,status,requested_at AS \"requestedAt\",rejection_reason AS \"rejectionReason\" FROM withdrawals WHERE staff_id=? ORDER BY id DESC",staff));}
    public List<Map<String,Object>>banks(String token){long staff=ServiceHttpClient.userId(identity.authenticate(token,"STAFF"));return db.queryForList("SELECT id,bank_code AS \"bankCode\",account_number AS \"accountNumber\",account_holder AS \"accountHolder\",status,is_default AS \"isDefault\" FROM staff_bank_accounts WHERE staff_id=? AND status<>'INACTIVE' ORDER BY is_default DESC,id",staff);}
    @Transactional public Map<String,Object>saveBank(String token,Map<String,Object>b){long staff=ServiceHttpClient.userId(identity.authenticate(token,"STAFF"));balance(staff,true);String bank=text(b,"bankCode",30,true),account=text(b,"accountNumber",50,true),holder=text(b,"accountHolder",160,true);if(!account.matches("[0-9]{5,30}"))throw bad("Số tài khoản phải có 5–30 chữ số.");var existing=db.queryForList("SELECT id FROM staff_bank_accounts WHERE staff_id=? AND bank_code=? AND account_number=?",Long.class,staff,bank,account);if(!existing.isEmpty())return Map.of("id",existing.getFirst(),"status",db.queryForObject("SELECT status FROM staff_bank_accounts WHERE id=?",String.class,existing.getFirst()));boolean first=!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM staff_bank_accounts WHERE staff_id=? AND status<>'INACTIVE')",Boolean.class,staff));long id=insert("INSERT INTO staff_bank_accounts(staff_id,bank_code,account_number,account_holder,is_default) VALUES (?,?,?,?,?)",staff,bank,account,holder,first);return Map.of("id",id,"status","PENDING");}
    @Transactional public Map<String,Object>withdraw(String token,Map<String,Object>b){long staff=ServiceHttpClient.userId(identity.authenticate(token,"STAFF"));long amount=number(b,"amount",50000,1000000000),bankId=number(b,"bankAccountId",1,Long.MAX_VALUE);String key=text(b,"requestKey",160,true);var wallet=balance(staff,true);var previous=db.queryForList("SELECT id,amount,bank_account_id,status FROM withdrawals WHERE staff_id=? AND request_key=?",staff,key);if(!previous.isEmpty()){var row=previous.getFirst();if(((Number)row.get("amount")).longValue()!=amount||((Number)row.get("bank_account_id")).longValue()!=bankId)throw new ResponseStatusException(HttpStatus.CONFLICT,"Mã yêu cầu đã dùng cho dữ liệu khác.");return Map.of("id",row.get("id"),"status",row.get("status"));}var banks=db.queryForList("SELECT * FROM staff_bank_accounts WHERE id=? AND staff_id=? AND status='VERIFIED' FOR SHARE",bankId,staff);if(banks.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Tài khoản ngân hàng chưa được Admin xác minh hoặc không thuộc bạn.");long available=((Number)wallet.get("available_balance")).longValue(),minimum=((Number)wallet.getOrDefault("minimum_balance",0L)).longValue();if(available-amount<minimum)throw new ResponseStatusException(HttpStatus.CONFLICT,"Số dư khả dụng không đủ hoặc thấp hơn mức tối thiểu.");long id=insert("INSERT INTO withdrawals(staff_id,balance_id,bank_account_id,bank_account_snapshot,amount,status,request_key) VALUES (?,?,?,CAST(? AS jsonb),?,'PENDING',?)",staff,wallet.get("id"),bankId,json.writeValueAsString(banks.getFirst()),amount,key);long balanceId=((Number)wallet.get("id")).longValue();ledger(balanceId,"DEBIT","AVAILABLE","HOLD",amount,id,"withdraw:"+id+":available");ledger(balanceId,"CREDIT","RESERVED","HOLD",amount,id,"withdraw:"+id+":reserved");db.update("UPDATE staff_balances SET available_balance=available_balance-?,reserved_balance=reserved_balance+?,version=version+1,updated_at=now() WHERE id=?",amount,amount,balanceId);event(staff,"WITHDRAWAL_REQUESTED",id,"Yêu cầu rút tiền đã được lưu, chờ xét duyệt; chưa chuyển tiền ngân hàng.");return Map.of("id",id,"status","PENDING");}
    private void event(long staff,String type,long reference,String message){insert("INSERT INTO outbox_events(aggregate_type,aggregate_id,event_type,payload) VALUES ('STAFF',?,?,CAST(? AS jsonb))",staff,type,json.writeValueAsString(Map.of("staffId",staff,"referenceId",reference,"message",message)));}
    private void ledger(long balance,String direction,String bucket,String type,long amount,long reference,String key){if(amount>0)insert("INSERT INTO wallet_transactions(balance_id,direction,bucket,transaction_type,amount,reference_id,idempotency_key) VALUES (?,?,?,?,?,?,?)",balance,direction,bucket,type,amount,reference,key);}
    public List<Map<String,Object>>adminBanks(String token){identity.authenticate(token,"ADMIN");return db.queryForList("SELECT id,staff_id AS \"staffId\",bank_code AS \"bankCode\",account_number AS \"accountNumber\",account_holder AS \"accountHolder\",status FROM staff_bank_accounts ORDER BY id DESC");}
    @Transactional public Map<String,Object>verifyBank(String token,long id,Map<String,Object>b){identity.authenticate(token,"ADMIN");String state=text(b,"status",20,true);if(!List.of("VERIFIED","INACTIVE").contains(state))throw bad("Chỉ được xác minh hoặc ngừng tài khoản.");if(db.update("UPDATE staff_bank_accounts SET status=? WHERE id=?",state,id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy tài khoản ngân hàng.");return Map.of("id",id,"status",state);}
    public List<Map<String,Object>>withdrawals(String token){identity.authenticate(token,"ADMIN");return db.queryForList("SELECT id,staff_id AS \"staffId\",amount,status,requested_at AS \"requestedAt\",approved_at AS \"approvedAt\",bank_account_snapshot::text AS \"bankAccount\",rejection_reason AS \"rejectionReason\" FROM withdrawals ORDER BY id DESC");}
    @Transactional public Map<String,Object>reviewWithdrawal(String token,long id,Map<String,Object>b){long admin=ServiceHttpClient.userId(identity.authenticate(token,"ADMIN"));var rows=db.queryForList("SELECT * FROM withdrawals WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy yêu cầu rút.");var w=rows.getFirst();String next=text(b,"status",20,true);if(next.equals(w.get("status")))return Map.of("id",id,"status",next);if(!List.of("PENDING","APPROVED").contains(w.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Yêu cầu đã kết thúc.");if(!List.of("APPROVED","REJECTED").contains(next))throw new ResponseStatusException(HttpStatus.CONFLICT,"Chỉ được duyệt hoặc từ chối. Chưa có nhà cung cấp xác minh chuyển tiền nên không được đánh dấu đã chi.");if("REJECTED".equals(next)){String reason=text(b,"reason",2000,true);var wallet=balance(((Number)w.get("staff_id")).longValue(),true);long amount=((Number)w.get("amount")).longValue(),balanceId=((Number)wallet.get("id")).longValue();ledger(balanceId,"DEBIT","RESERVED","RELEASE",amount,id,"withdraw:"+id+":release-reserved");ledger(balanceId,"CREDIT","AVAILABLE","RELEASE",amount,id,"withdraw:"+id+":release-available");db.update("UPDATE staff_balances SET reserved_balance=reserved_balance-?,available_balance=available_balance+?,version=version+1,updated_at=now() WHERE id=?",amount,amount,balanceId);db.update("UPDATE withdrawals SET status='REJECTED',rejection_reason=?,approved_by=? WHERE id=?",reason,admin,id);}else db.update("UPDATE withdrawals SET status='APPROVED',approved_by=?,approved_at=now() WHERE id=?",admin,id);event(((Number)w.get("staff_id")).longValue(),"WITHDRAWAL_REVIEWED",id,"Yêu cầu rút tiền: "+next+". Duyệt yêu cầu chưa đồng nghĩa đã chuyển tiền.");return Map.of("id",id,"status",next);}
    public List<Map<String,Object>>transactions(String token){identity.authenticate(token,"ADMIN");var result=new ArrayList<Map<String,Object>>();for(var p:db.queryForList("SELECT id,booking_id,customer_id,amount,status,payment_method,created_at,admin_note FROM payments ORDER BY id DESC")){result.add(transaction(p,"PAYMENT","customer_id"));}for(var w:db.queryForList("SELECT id,staff_id,amount,status,requested_at AS created_at,rejection_reason AS admin_note FROM withdrawals ORDER BY id DESC")){result.add(transaction(w,"PAYOUT","staff_id"));}for(var r:db.queryForList("SELECT r.id,p.booking_id,p.customer_id,r.amount,r.status,p.payment_method,r.requested_at AS created_at,r.admin_note FROM refunds r JOIN payments p ON p.id=r.payment_id ORDER BY r.id DESC")){result.add(transaction(r,"REFUND","customer_id"));}return result;}
    Map<String,Object>transaction(Map<String,Object>row,String type,String actor){var result=new LinkedHashMap<String,Object>();result.put("id",type+"-"+row.get("id"));result.put("recordId",row.get("id"));result.put("type",type);result.put("bookingId",row.get("booking_id"));result.put("actorId",row.get(actor));result.put("amount",row.get("amount"));result.put("status",List.of("PAID","PROCESSED").contains(row.get("status"))?"SUCCESS":List.of("FAILED","REJECTED","CANCELLED").contains(row.get("status"))?"FAILED":"PENDING");result.put("rawStatus",row.get("status"));result.put("paymentMethod",Objects.equals(row.get("payment_method"),"CASH")?"CASH":"BANK_TRANSFER");result.put("platformFee",0);result.put("createdAt",row.get("created_at"));result.put("description",Objects.toString(row.get("admin_note"),""));return result;}
    @Transactional public Map<String,Object>note(String token,String type,long id,Map<String,Object>b){identity.authenticate(token,"ADMIN");String table=type.equals("PAYMENT")?"payments":type.equals("REFUND")?"refunds":null;if(table==null)throw bad("Giao dịch rút tiền phải xử lý qua yêu cầu rút.");var rows=db.queryForList("SELECT status FROM "+table+" WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy giao dịch.");String current=List.of("PAID","PROCESSED").contains(rows.getFirst().get("status"))?"SUCCESS":List.of("FAILED","REJECTED","CANCELLED").contains(rows.getFirst().get("status"))?"FAILED":"PENDING";if(!current.equals(b.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Trạng thái tiền phải được xác nhận bởi nghiệp vụ thanh toán. Chỉ được lưu ghi chú đối soát tại đây.");db.update("UPDATE "+table+" SET admin_note=? WHERE id=?",text(b,"description",2000,false),id);return Map.of("id",id,"status",current);}
    public List<Map<String,Object>>invoices(String token){var user=identity.authenticate(token,"ADMIN","CUSTOMER");return db.queryForList("SELECT id,booking_id AS \"bookingId\",invoice_number AS \"invoiceNumber\",subtotal,discount_amount AS \"discountAmount\",total_amount AS \"totalAmount\",status,issued_at AS \"issuedAt\" FROM invoices"+("CUSTOMER".equals(user.get("role"))?" WHERE customer_id=?":"")+" ORDER BY id DESC","CUSTOMER".equals(user.get("role"))?new Object[]{user.get("id")}:new Object[]{});}
    public Map<String,Object>paymentProvider(String token,long id){var user=identity.authenticate(token,"CUSTOMER");var b=booking.get("/api/v1/booking/bookings/"+id,token);if(((Number)b.get("customerId")).longValue()!=ServiceHttpClient.userId(user))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy đơn của bạn.");throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Chưa cấu hình nhà cung cấp PayOS/VietQR để tạo QR và xác minh giao dịch thật.");}
    public Map<String,Object>policy(String token){identity.authenticate(token,"ADMIN");var rows=db.queryForList("SELECT name,number_value AS value FROM finance_settings");return Map.of("settings",rows);}
    @Transactional public Map<String,Object>savePolicy(String token,Map<String,Object>b){long admin=ServiceHttpClient.userId(identity.authenticate(token,"ADMIN"));long percent=number(b,"platformFeePercent",0,100);db.update("INSERT INTO finance_settings(name,number_value,updated_by) VALUES ('platformFeePercent',?,?) ON CONFLICT(name) DO UPDATE SET number_value=EXCLUDED.number_value,updated_by=EXCLUDED.updated_by,updated_at=now()",percent,admin);return policy(token);}
    @Transactional public Map<String,Object>cashReceipt(String token,long id,Map<String,Object>b){identity.authenticate(token,"ADMIN");if(!Boolean.TRUE.equals(b.get("cashReceived")))throw bad("Cần xác nhận đã thực nhận tiền mặt.");var book=booking.get("/api/v1/booking/bookings/"+id,token);if(!"CASH".equals(book.get("paymentMethod"))||List.of("CANCELLED","REFUNDED").contains(book.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Đơn không thuộc luồng thu tiền mặt còn hiệu lực.");db.execute("SELECT pg_advisory_xact_lock("+id+")");var old=db.queryForList("SELECT id,status FROM payments WHERE booking_id=? AND payment_method='CASH' AND status='PAID'",id);if(!old.isEmpty())return Map.of("id",old.getFirst().get("id"),"status","PAID");long amount=((Number)book.get("totalAmount")).longValue();if(amount<=0)throw bad("Đơn không có số tiền cần thu.");long payment=insert("INSERT INTO payments(booking_id,customer_id,payment_code,amount,payment_method,provider,status,paid_at,admin_note) VALUES (?,?,?,?,'CASH','MANUAL_CASH_RECEIPT','PAID',now(),?)",id,book.get("customerId"),"CASH-"+UUID.randomUUID(),amount,"Admin xác nhận đã thực nhận tiền mặt.");insert("INSERT INTO outbox_events(aggregate_type,aggregate_id,event_type,payload) VALUES ('PAYMENT',?,'PAYMENT_CONFIRMED',CAST(? AS jsonb))",payment,json.writeValueAsString(Map.of("bookingId",id)));return Map.of("id",payment,"status","PAID");}
    public void syncPayment(String token,long id){booking.call("POST","/api/v1/booking/admin/bookings/"+id+"/verify-payment",token,Map.of());}
    public Map<String,Object>paymentStatus(String token,long id){identity.authenticate(token,"ADMIN","CUSTOMER","STAFF");booking.get("/api/v1/booking/bookings/"+id,token);long paid=db.queryForObject("SELECT coalesce(sum(amount),0) FROM payments WHERE booking_id=? AND status IN ('PAID','PARTIALLY_REFUNDED','REFUNDED')",Long.class,id);long refunded=db.queryForObject("SELECT coalesce(sum(r.amount),0) FROM refunds r JOIN payments p ON p.id=r.payment_id WHERE p.booking_id=? AND r.status='PROCESSED'",Long.class,id);return Map.of("paidAmount",paid,"refundedAmount",refunded);}
    @SuppressWarnings("unchecked") @Transactional public Map<String,Object>settle(String token,long id){identity.authenticate(token,"ADMIN");var book=booking.get("/api/v1/booking/bookings/"+id,token);if(!"COMPLETED".equals(book.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Chỉ lập quyết toán và hóa đơn sau khi đơn hoàn thành.");db.execute("SELECT pg_advisory_xact_lock("+id+")");var invoices=db.queryForList("SELECT id FROM invoices WHERE booking_id=?",Long.class,id);if(!invoices.isEmpty())return Map.of("invoiceId",invoices.getFirst(),"status",db.queryForObject("SELECT status FROM invoices WHERE id=?",String.class,invoices.getFirst()));long total=((Number)book.get("totalAmount")).longValue();long paid=db.queryForObject("SELECT coalesce(sum(amount),0) FROM payments WHERE booking_id=? AND status='PAID'",Long.class,id);if(paid<total)throw new ResponseStatusException(HttpStatus.CONFLICT,"Chưa xác minh đủ số tiền thanh toán trong Finance.");var settings=db.queryForList("SELECT number_value FROM finance_settings WHERE name='platformFeePercent'",java.math.BigDecimal.class);if(settings.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Admin cần lưu chính sách phí hệ thống trước khi quyết toán.");var people=((List<Map<String,Object>>)book.get("assignments")).stream().filter(a->"COMPLETED".equals(a.get("status"))).map(a->((Number)a.get("staffId")).longValue()).distinct().sorted().toList();if(people.size()!=((Number)book.get("requiredStaffCount")).intValue())throw new ResponseStatusException(HttpStatus.CONFLICT,"Chưa đủ nhân viên hoàn thành để quyết toán.");long base=((Number)book.get("packagePrice")).longValue(),addons=((Number)book.get("addOnsTotal")).longValue(),discount=((Number)book.get("discountAmount")).longValue();long order=insert("INSERT INTO orders(booking_id,order_code,subtotal,add_on_amount,discount_amount,total_amount,payment_method,status,finalized_at) VALUES (?,?,?,?,?,?,?,'FINALIZED',now())",id,"ORDER-"+UUID.randomUUID(),base,addons,discount,total,book.get("paymentMethod"));String serviceName=Objects.toString(((Map<String,Object>)book.get("service")).get("name"),"Dịch vụ");insert("INSERT INTO order_details(order_id,item_type,item_name,quantity,unit_price,total_price) VALUES (?,'PACKAGE',?,1,?,?)",order,serviceName,base,base);if(addons>0)insert("INSERT INTO order_details(order_id,item_type,item_name,quantity,unit_price,total_price) VALUES (?,'ADD_ON','Các hạng mục bổ sung',1,?,?)",order,addons,addons);
        long invoice=insert("INSERT INTO invoices(order_id,booking_id,customer_id,invoice_number,customer_snapshot,service_snapshot,subtotal,discount_amount,total_amount,status) VALUES (?,?,?,?,CAST(? AS jsonb),CAST(? AS jsonb),?,?,?,'PAID')",order,id,book.get("customerId"),"INV-"+UUID.randomUUID(),json.writeValueAsString(book.get("address")),json.writeValueAsString(book.get("service")),base+addons,discount,total);insert("INSERT INTO invoice_items(invoice_id,name,quantity,unit_price,total_price) VALUES (?,?,1,?,?)",invoice,serviceName,base+addons,base+addons);double hours=java.time.Duration.between(java.time.Instant.parse((String)book.get("startsAt")),java.time.Instant.parse((String)book.get("endsAt"))).toMinutes()/60.0;
        for(int index=0;index<people.size();index++){long staff=people.get(index),share=total/people.size()+(index<total%people.size()?1:0);long fee=java.math.BigDecimal.valueOf(share).multiply(settings.getFirst()).divide(java.math.BigDecimal.valueOf(100),0,java.math.RoundingMode.DOWN).longValueExact();var wallet=balance(staff,true);long balanceId=((Number)wallet.get("id")).longValue();long income=insert("INSERT INTO staff_incomes(staff_id,booking_id,balance_id,working_hours,service_amount,platform_fee,staff_amount,status,income_date,settled_at) VALUES (?,?,?,?,?,?,?,'SETTLED',(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,now())",staff,id,balanceId,hours,share,fee,share-fee);ledger(balanceId,"CREDIT","AVAILABLE","EARNING",share-fee,income,"booking:"+id+":staff:"+staff+":earning");db.update("UPDATE staff_balances SET available_balance=available_balance+?,total_earned=total_earned+?,version=version+1,updated_at=now() WHERE id=?",share-fee,share-fee,balanceId);}
        db.update("UPDATE payments SET order_id=? WHERE booking_id=? AND status='PAID'",order,id);for(long person:people)event(person,"EARNING_SETTLED",id,"Thu nhập đơn #"+id+" đã được quyết toán. Xem chi tiết tại ví nhân viên.");return Map.of("invoiceId",invoice,"status","PAID");}
    public List<Map<String,Object>>adjustments(String token){identity.authenticate(token,"ADMIN");return Map.of("rewards",db.queryForList("SELECT * FROM rewards ORDER BY id DESC"),"penalties",db.queryForList("SELECT * FROM penalties ORDER BY id DESC")).entrySet().stream().flatMap(e->e.getValue().stream().map(r->{r.put("kind",e.getKey().equals("rewards")?"REWARD":"PENALTY");return r;})).toList();}
    @Transactional public Map<String,Object>requestReward(String token,long staff,Map<String,Object>b){identity.authenticate(token,"ADMIN");String period=Objects.toString(b.get("period"),"CURRENT");if(!List.of("CURRENT","PREVIOUS").contains(period))throw bad("Kỳ thưởng không hợp lệ.");var operations=booking.get("/api/v1/booking/admin/staff/"+staff+"/operations?period="+period,token);var wallet=balance(staff,true);var date=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Ho_Chi_Minh"));var from=date.withDayOfMonth(1).minusMonths(period.equals("PREVIOUS")?1:0);var to=from.plusMonths(1).minusDays(1);long monthlyIncome=db.queryForObject("SELECT coalesce(sum(staff_amount),0) FROM staff_incomes WHERE staff_id=? AND status='SETTLED' AND income_date>=? AND income_date<=?",Long.class,staff,from,to);List<Long>ids=new ArrayList<>();for(String kind:List.of("tripsBonus","incomeBonus","ratingBonus")){if(!Boolean.TRUE.equals(b.get(kind)))continue;boolean qualified=kind.equals("tripsBonus")?((Number)operations.get("completedBookings")).longValue()>=150:kind.equals("incomeBonus")?monthlyIncome>=20000000:((Number)operations.get("averageRating")).doubleValue()>=4.9&&((Number)operations.get("reviewCount")).intValue()>0;if(!qualified)throw new ResponseStatusException(HttpStatus.CONFLICT,"Nhân viên chưa đạt điều kiện thưởng "+kind+" theo dữ liệu thật.");var prior=db.queryForList("SELECT id FROM rewards WHERE staff_id=? AND reward_type=? AND period_start=? AND period_end=?",Long.class,staff,kind,from,to);if(!prior.isEmpty()){ids.add(prior.getFirst());continue;}long amount=kind.equals("tripsBonus")?500000:kind.equals("incomeBonus")?1000000:300000;ids.add(insert("INSERT INTO rewards(staff_id,reward_type,period_start,period_end,revenue,amount,reason,status) VALUES (?,?,?,?,?,?,?,'PENDING')",staff,kind,from,to,monthlyIncome,amount,"Đề xuất thưởng theo mốc KPI, chờ phê duyệt."));}if(ids.isEmpty())throw bad("Vui lòng chọn ít nhất một khoản thưởng đủ điều kiện.");return Map.of("ids",ids,"status","PENDING");}
    @Transactional public Map<String,Object>requestPenalty(String token,long staff,Map<String,Object>b){identity.authenticate(token,"ADMIN");booking.get("/api/v1/booking/admin/staff/"+staff+"/operations",token);balance(staff,true);long amount=number(b,"amount",1,1000000000);String reason=text(b,"reason",2000,true),key=text(b,"requestKey",160,true);var prior=db.queryForList("SELECT id,amount,reason FROM penalties WHERE staff_id=? AND request_key=?",staff,key);if(!prior.isEmpty()){var old=prior.getFirst();if(((Number)old.get("amount")).longValue()!=amount||!reason.equals(old.get("reason")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Đề xuất phạt đã tồn tại với nội dung khác.");return Map.of("id",old.get("id"),"status","PENDING");}return Map.of("id",insert("INSERT INTO penalties(staff_id,penalty_type,amount,reason,status,request_key) VALUES (?,'ADMIN_REVIEW',?,?,'PENDING',?)",staff,amount,reason,key),"status","PENDING");}
    @Transactional public Map<String,Object>applyAdjustment(String token,String kind,long id){identity.authenticate(token,"ADMIN");String table=kind.equals("REWARD")?"rewards":kind.equals("PENALTY")?"penalties":null;if(table==null)throw bad("Loại điều chỉnh không hợp lệ.");var list=db.queryForList("SELECT * FROM "+table+" WHERE id=? FOR UPDATE",id);if(list.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy đề xuất.");var entry=list.getFirst();if("APPLIED".equals(entry.get("status")))return Map.of("id",id,"status","APPLIED");if(!"PENDING".equals(entry.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Đề xuất không còn chờ duyệt.");var wallet=balance(((Number)entry.get("staff_id")).longValue(),true);long amount=((Number)entry.get("amount")).longValue(),balanceId=((Number)wallet.get("id")).longValue();if(kind.equals("PENALTY")&&((Number)wallet.get("available_balance")).longValue()<amount)throw new ResponseStatusException(HttpStatus.CONFLICT,"Số dư không đủ; giữ đề xuất phạt ở trạng thái chờ xử lý.");ledger(balanceId,kind.equals("REWARD")?"CREDIT":"DEBIT","AVAILABLE",kind,amount,id,kind+":"+id+":apply");db.update("UPDATE staff_balances SET available_balance=available_balance+?,version=version+1,updated_at=now() WHERE id=?",kind.equals("REWARD")?amount:-amount,balanceId);db.update("UPDATE "+table+" SET status='APPLIED' WHERE id=?",id);event(((Number)entry.get("staff_id")).longValue(),kind+"_APPLIED",id,"Khoản điều chỉnh "+kind+" đã được ghi sổ: "+amount+" VNĐ.");return Map.of("id",id,"status","APPLIED");}
}
